'use client'

import { useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { motion } from 'motion/react'
import { clsx } from 'clsx'
import { useGame } from '@/lib/game-context'
import { StarfieldBackground, GlassPanel } from '@/components/ui'
import { items } from '@/lib/data/items'

const categoryColors: Record<string, string> = {
  tool: 'bg-nebula/20 text-nebula border-nebula/30',
  protocol: 'bg-signal/20 text-signal border-signal/30',
  pattern: 'bg-terracotta/20 text-terracotta border-terracotta/30',
  defense: 'bg-starlight/15 text-starlight border-starlight/30',
}

const categoryIcons: Record<string, string> = {
  tool: '#4a6fa5',
  protocol: '#6b9e78',
  pattern: '#c17147',
  defense: '#e8e0d4',
}

export default function InventoryPage() {
  const { state, loading } = useGame()
  const router = useRouter()

  useEffect(() => {
    if (!loading && !state) router.push('/')
  }, [loading, state, router])

  if (loading || !state) return null

  const acquiredCount = state.inventory.length

  return (
    <div className="relative min-h-screen overflow-hidden">
      <StarfieldBackground speed={0.3} />

      <main className="relative z-10 max-w-5xl mx-auto px-4 py-8 pb-24 space-y-6">
        {/* Page header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring' as const, stiffness: 100, damping: 15 }}
        >
          <div className="text-center space-y-2">
            <h1 className="font-display text-3xl sm:text-4xl text-starlight tracking-widest uppercase">
              Inventory
            </h1>
            <p className="font-mono text-sm text-starlight-dim">
              {acquiredCount} / {items.length} Items Collected
            </p>
          </div>
        </motion.div>

        {/* Items grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {items.map((item, index) => {
            const acquired = state.inventory.includes(item.id)

            return (
              <motion.div
                key={item.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{
                  type: 'spring' as const,
                  stiffness: 100,
                  damping: 15,
                  delay: 0.05 * index,
                }}
              >
                <GlassPanel
                  padding="md"
                  glow={acquired ? getCategoryGlow(item.category) : undefined}
                  className={clsx(!acquired && 'opacity-40')}
                >
                  <div className="space-y-3">
                    {/* Icon placeholder */}
                    <div className="flex items-start justify-between">
                      <div
                        className={clsx(
                          'w-12 h-12 rounded-full flex items-center justify-center text-lg font-display border-2',
                          acquired ? 'border-opacity-60' : 'border-glass-border'
                        )}
                        style={
                          acquired
                            ? {
                                borderColor: categoryIcons[item.category],
                                backgroundColor: `${categoryIcons[item.category]}20`,
                                color: categoryIcons[item.category],
                              }
                            : { color: '#e8e0d450' }
                        }
                      >
                        {acquired ? item.name[0] : '?'}
                      </div>

                      {/* Category badge */}
                      <span
                        className={clsx(
                          'inline-flex items-center px-2 py-0.5 rounded-full text-xs font-mono uppercase tracking-wider border',
                          categoryColors[item.category]
                        )}
                      >
                        {item.category}
                      </span>
                    </div>

                    {/* Name */}
                    <h3 className="font-display text-lg text-starlight tracking-wide">
                      {acquired ? item.name : '???'}
                    </h3>

                    {/* Real-world tool */}
                    {acquired && (
                      <p className="font-mono text-xs text-nebula">
                        {item.realWorldTool}
                      </p>
                    )}

                    {/* Description */}
                    <p className="font-body text-sm text-starlight-dim leading-relaxed">
                      {acquired ? item.description : '???'}
                    </p>
                  </div>
                </GlassPanel>
              </motion.div>
            )
          })}
        </div>
      </main>
    </div>
  )
}

function getCategoryGlow(category: string): 'nebula' | 'signal' | 'terracotta' | 'starlight' {
  switch (category) {
    case 'tool':
      return 'nebula'
    case 'protocol':
      return 'signal'
    case 'pattern':
      return 'terracotta'
    case 'defense':
      return 'starlight'
    default:
      return 'nebula'
  }
}

'use client'

import { useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { motion } from 'motion/react'
import { clsx } from 'clsx'
import { useGame } from '@/lib/game-context'
import { StarfieldBackground, GlassPanel } from '@/components/ui'
import { crewMembers } from '@/lib/data/crew'

const locationHints: Record<string, string> = {
  start: 'Starting Crew',
  'agent-academy-m1': 'Agent Academy',
  'agent-academy-m3': 'Agent Academy',
  'agent-academy-m5': 'Agent Academy',
  'security-fortress-m1': 'Security Fortress',
}

function getLocationHint(recruitedAt: string): string {
  if (locationHints[recruitedAt]) return locationHints[recruitedAt]
  // Fallback: parse the location from the ID (e.g., 'some-place-m2' -> 'Some Place')
  const parts = recruitedAt.replace(/-m\d+$/, '').split('-')
  return parts.map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join(' ')
}

function getCrewGlow(color: string): 'nebula' | 'signal' | 'terracotta' | 'starlight' {
  switch (color) {
    case '#4a6fa5':
      return 'nebula'
    case '#6b9e78':
      return 'signal'
    case '#c17147':
      return 'terracotta'
    case '#e8e0d4':
      return 'starlight'
    default:
      return 'nebula'
  }
}

export default function CrewPage() {
  const { state, loading } = useGame()
  const router = useRouter()

  useEffect(() => {
    if (!loading && !state) router.push('/')
  }, [loading, state, router])

  if (loading || !state) return null

  const recruitedCount = state.crew.length

  return (
    <div className="relative min-h-screen overflow-hidden">
      <StarfieldBackground speed={0.3} />

      <main className="relative z-10 max-w-5xl mx-auto px-4 py-8 pb-24 space-y-6">
        {/* Page header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring' as const, stiffness: 100, damping: 15 }}
        >
          <div className="text-center space-y-2">
            <h1 className="font-display text-3xl sm:text-4xl text-starlight tracking-widest uppercase">
              Your Crew
            </h1>
            <p className="font-mono text-sm text-starlight-dim">
              {recruitedCount} / {crewMembers.length} Crew Recruited
            </p>
          </div>
        </motion.div>

        {/* Crew grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {crewMembers.map((member, index) => {
            const recruited = state.crew.includes(member.id)

            return (
              <motion.div
                key={member.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{
                  type: 'spring' as const,
                  stiffness: 100,
                  damping: 15,
                  delay: 0.08 * index,
                }}
              >
                <GlassPanel
                  padding="md"
                  glow={recruited ? getCrewGlow(member.color) : undefined}
                  className={clsx(!recruited && 'opacity-50')}
                >
                  <div className="space-y-4">
                    {/* Portrait placeholder */}
                    <div className="flex justify-center">
                      <div
                        className={clsx(
                          'w-20 h-20 rounded-full flex items-center justify-center text-2xl font-display border-2 transition-all',
                          recruited ? 'border-opacity-60' : 'border-glass-border'
                        )}
                        style={
                          recruited
                            ? {
                                borderColor: member.color,
                                backgroundColor: `${member.color}20`,
                                color: member.color,
                              }
                            : { color: '#e8e0d450' }
                        }
                      >
                        {recruited ? member.name[0] : '?'}
                      </div>
                    </div>

                    {/* Name */}
                    <div className="text-center">
                      <h3
                        className="font-display text-xl tracking-wide"
                        style={recruited ? { color: member.color } : undefined}
                      >
                        {recruited ? member.name : 'Unknown Crew Member'}
                      </h3>

                      {/* Role */}
                      <p className="text-sm text-starlight-dim mt-1">
                        {recruited ? member.role : '???'}
                      </p>
                    </div>

                    {/* Agent phase badge */}
                    {recruited && (
                      <div className="flex justify-center">
                        <span
                          className="inline-flex items-center px-3 py-1 rounded-full text-xs font-mono uppercase tracking-wider border"
                          style={{
                            color: member.color,
                            borderColor: `${member.color}40`,
                            backgroundColor: `${member.color}15`,
                          }}
                        >
                          {member.agentPhase}
                        </span>
                      </div>
                    )}

                    {/* Description or recruit hint */}
                    {recruited ? (
                      <p className="font-body text-sm text-starlight-dim leading-relaxed text-center">
                        {member.description}
                      </p>
                    ) : (
                      <p className="font-body text-sm text-starlight-dim/70 text-center italic">
                        Recruit at {getLocationHint(member.recruitedAt)}
                      </p>
                    )}

                    {/* Quote */}
                    {recruited && (
                      <p className="text-sm italic text-starlight-dim/70 text-center border-t border-glass-border pt-3">
                        &ldquo;{member.quote}&rdquo;
                      </p>
                    )}
                  </div>
                </GlassPanel>
              </motion.div>
            )
          })}
        </div>
      </main>
    </div>
  )
}
